async function applyShopListingPatch(db, serverId, action, listing, shopId, itemKey, previousItemKey, syncedAt) {
  let upserted = false;
  let deleted = false;
  const affected = /* @__PURE__ */ new Set();
  if (action === "delete") {
    const sid = str3(listing?.shop_id) || shopId;
    if (!sid) return { upserted: false, deleted: false, priceItems: 0 };
    const existing = await db.prepare(`SELECT item_key FROM rootstat_shop_listings WHERE server_id = ? AND shop_id = ?`).bind(serverId, sid).first();
    if (existing?.item_key) affected.add(str3(existing.item_key));
    if (itemKey) affected.add(normalizeItemKey(itemKey));
    if (previousItemKey) affected.add(normalizeItemKey(previousItemKey));
    await db.prepare(`DELETE FROM rootstat_shop_listings WHERE server_id = ? AND shop_id = ?`).bind(serverId, sid).run();
    deleted = true;
  } else if (listing) {
    upserted = await upsertOneShopListing(db, serverId, listing, syncedAt);
    const key = normalizeItemKey(str3(listing.item_key));
    if (key) affected.add(key);
    if (previousItemKey) affected.add(normalizeItemKey(previousItemKey));
  }
  let priceItems = 0;
  for (const key of affected) {
    if (!key) continue;
    if (await recomputeShopPriceForItem(db, serverId, key, syncedAt)) priceItems++;
  }
  return { upserted, deleted, priceItems };
}
async function handleShopListingSync(request, env2) {
  const server = await validateServerAuth(env2, request);
  if (server instanceof Response) return server;
  let body = {};
  try {
    body = record2(JSON.parse(await request.text()));
  } catch {
    return json({ detail: "Invalid JSON body." }, 400);
  }
  const actionRaw = str3(body.action).toLowerCase();
  const action = actionRaw === "delete" ? "delete" : "upsert";
  const syncedAt = str3(body.synced_at) || nowIso7();
  const listing = action === "upsert" && body.listing && typeof body.listing === "object" ? record2(body.listing) : null;
  const shopId = str3(body.shop_id);
  const itemKey = str3(body.item_key);
  const previousItemKey = str3(body.previous_item_key);
  if (action === "upsert" && !listing) {
    return json({ detail: "listing required for upsert." }, 400);
  }
  if (action === "delete" && !shopId && !str3(listing?.shop_id)) {
    return json({ detail: "shop_id required for delete." }, 400);
  }
  try {
    const primary = await applyShopListingPatch(
      env2.DB,
      server.serverId,
      action,
      listing,
      shopId,
      itemKey,
      previousItemKey,
      syncedAt
    );
    if (server.serverId !== CANONICAL_ROOTMC_SERVER) {
      await applyShopListingPatch(
        env2.DB,
        CANONICAL_ROOTMC_SERVER,
        action,
        listing,
        shopId,
        itemKey,
        previousItemKey,
        syncedAt
      );
    }
    return json({
      ok: true,
      action,
      shop_id: shopId || str3(listing?.shop_id) || null,
      upserted: primary.upserted,
      deleted: primary.deleted,
      price_items_updated: primary.priceItems,
      synced_at: syncedAt
    });
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    console.error("shop_listing_sync_failed", server.serverId, msg.slice(0, 500));
    return json({ detail: `Shop listing sync failed: ${msg.slice(0, 240)}` }, 500);
  }
}
