async function handleG2Routes(request, env2, sub, method) {
  if (!isG2Worker(env2)) {
    if (sub.startsWith("/g2/") || sub.startsWith("/v2/")) {
      return json(
        {
          ok: false,
          error: "gen2_retired",
          detail: "Gen 2 API retired \u2014 Claims uses https://api.rootmc.info"
        },
        404
      );
    }
    return null;
  }
  const publicRes = await handleG2EconomyPublicRoutes(request, env2, sub, method);
  if (publicRes) return publicRes;
  if (method === "POST" && sub === "/rootmc/server/heartbeat") {
    return handleG2CompatServerHeartbeat(request, env2);
  }
  if (!sub.startsWith("/v2/")) {
    return null;
  }
  const url = new URL(request.url);
  const force = url.searchParams.get("force") === "1";
  if (method === "POST" && sub === "/v2/realm/snapshot/economy") {
    return handleG2EconomySnapshot(request, env2, force);
  }
  if (method === "POST" && sub === "/v2/realm/snapshot/bonds") {
    return handleG2BondsSnapshot(request, env2);
  }
  if (method === "POST" && sub === "/v2/realm/snapshot/stats") {
    return handleG2StatsSnapshot(request, env2);
  }
  if (method === "POST" && sub === "/v2/realm/heartbeat") {
    return handleG2Heartbeat(request, env2);
  }
  if (method === "GET" && sub === "/v2/realm/status") {
    return handleG2RealmStatus(request, env2);
  }
  if (method === "GET" && sub === "/v2/health") {
    return json({ ok: true, generation: "gen2", worker: env2.WORKER_SHARD || "rootmc-api-g2" });
  }
  if (method === "POST" && sub === "/v2/cron/hourly-discord") {
    const result = await runG2LiveEconomyStatusPost(env2);
    return json(result, result.ok ? 200 : 500);
  }
  return json({ ok: false, error: "not_found" }, 404);
}
__name(handleG2Routes, "handleG2Routes");

